#!/usr/bin/env python3
"""Generate docs/TITLES.md from symbols/titles/TITLES_INVENTORY.csv and TITLES_SYMBOL_TABLE.csv (both models)."""
import csv, collections, os, re
R = os.path.abspath(os.path.dirname(__file__) + '/../..')
def load(m):
    inv = list(csv.DictReader(open(f'{R}/{"n3ds/symbols/titles" if m == "n3ds" else "o3ds/symbols_titles"}/TITLES_INVENTORY.csv')))
    sym = list(csv.DictReader(open(f'{R}/{"n3ds/symbols/titles" if m == "n3ds" else "o3ds/symbols_titles"}/TITLES_SYMBOL_TABLE.csv')))
    return inv, sym
out = ['# Titles (applications, applets, system / shared data, TWL) - auto-generated by tools/make_titles_doc.py\n',
       'Everything under `o3ds/extracted` / `o3ds/updates` and `n3ds/updates` that is not a sysmodule or FIRM was decrypted and unpacked with `tools/extract_titles.py`',
       '(`o3ds/decrypted_titles/`, `n3ds/decrypted_titles/`: per title `code.bin`, `exheader.bin`, `exefs_dir/`, full `romfs/` tree, `analysis/`).',
       'Each code image was analysed by `tools/title_analysis.py` (radare2 function list, SVC wrappers, IPC candidates, service strings, pointer tables, **C++ RTTI recovery**,',
       'source-path attribution, string-referencing functions) and cross-named by `tools/library_propagation.py` (masked-byte identity with functions named in any other binary, either model).\n',
       'Symbol rows: `n3ds/symbols/titles/TITLES_SYMBOL_TABLE.csv` and `o3ds/symbols_titles/TITLES_SYMBOL_TABLE.csv`; per-title inventory: `TITLES_INVENTORY.csv` next to them; all cross-binary matches: `n3ds/symbols/titles/LIBRARY_MATCHES.csv`.\n',
       'Confidence levels of these rows: `derived_rtti` (class names read from the binary\'s own RTTI strings; virtual-slot / vptr-init names add only the index/address), `derived_source_ref` (function references a source path string), `derived_string_ref`, `derived_structural` (SVC wrapper, IPC, service strings, pointer tables), `library_match` (masked bytes identical to a named function elsewhere).\n']
for m in ('n3ds', 'o3ds'):
    inv, sym = load(m)
    ns = collections.defaultdict(collections.Counter); roots = collections.defaultdict(collections.Counter)
    for r in sym:
        if r['kind'] == 'rtti_typeinfo':
            mm = re.search(r'class "([^"]+)"', r['technical_evidence'])
            if mm: ns[r['title_id']][mm.group(1).split('::')[0] + ('::' + mm.group(1).split('::')[1] if '::' in mm.group(1) and len(mm.group(1).split('::')) > 2 else '')] += 1
        if r['kind'] == 'source_path_string':
            p = r['technical_evidence'].replace('\\', '/'); roots[r['title_id']]['/'.join(p.split('/')[:3])] += 1
    out += [f'\n## {m.upper()} - {len(inv)} titles\n', '| TitleID | Title | Version | vs other model | code KiB | RTTI classes | vtables | vptr-init fns | source-ref fns | string-ref fns | library matches | SVC wrappers | romfs files | main services (ExHeader) |', '|---|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---|']
    for x in inv:
        out.append(f"| `{x['title_id']}` | {x['directory_name']} | {x['title_version']} | {x['relation_to_other_model'].replace('_', ' ')} | {int(x['code_bytes']) // 1024} | {x['rtti_classes']} | {x['rtti_vtables']} | {x['rtti_vptr_init_functions']} | {x['source_ref_functions']} | {x['string_ref_functions']} | {x['library_matches']} | {x['svc_wrappers']} | {x['romfs_files']} | {' '.join(x['service_access'].split()[:8])} |")
    out.append('\n### Recovered C++ namespaces / source roots per title\n')
    for x in inv:
        t = x['title_id']
        if ns[t] or roots[t]:
            out.append(f"* **{x['directory_name']}** (`{t}`): namespaces {', '.join(f'`{k}` ({v})' for k, v in ns[t].most_common(6)) or '-'}; source-path roots {', '.join(f'`{k}` ({v})' for k, v in roots[t].most_common(2)) or '-'}")
open(f'{R}/n3ds/docs/TITLES.md', 'w').write('\n'.join(out) + '\n'); print('ok', len(out))
